args.CodeContent:
$targetPath = "C:\Users\renu5\Downloads\nishe found"
$deleteListPath = Join-Path $targetPath "delete_list.txt"
$logPath = Join-Path $targetPath "compression_log.txt"

# Find all mp4 files >= 20MB and don't end with " C.mp4"
$files = Get-ChildItem -Path $targetPath -Filter "*.mp4" -Recurse | Where-Object {
    $_.Length -ge 20MB -and $_.Name -notmatch " C\.mp4$"
}

$totalProcessed = 0
$totalOriginalSize = 0
$totalCompressedSize = 0

Write-Host "Found $($files.Count) videos to process."

foreach ($file in $files) {
    $basename = $file.BaseName
    $extension = $file.Extension
    $dir = $file.DirectoryName

    $outputFile = Join-Path $dir "$basename C$extension"

    if (Test-Path $outputFile) {
        Write-Host "Skipping $($file.Name): Compressed version already exists."
        continue
    }

    Write-Host "Compressing $($file.Name)..."
    $originalSizeMB = $file.Length / 1MB

    # Run FFmpeg
    $ffmpegArgs = @("-y", "-i", $file.FullName, "-c:v", "libx264", "-crf", "28", "-preset", "fast", "-c:a", "aac", "-b:a", "128k", $outputFile)
    & ffmpeg @ffmpegArgs

    if ($LASTEXITCODE -eq 0 -and (Test-Path $outputFile)) {
        $compressedFile = Get-Item $outputFile
        $compressedSizeMB = $compressedFile.Length / 1MB
        $savedPercent = 0
        if ($originalSizeMB -gt 0) {
            $savedPercent = (($originalSizeMB - $compressedSizeMB) / $originalSizeMB) * 100
        }

        $logMessage = "Compressed $($file.Name): Original Size: $([math]::Round($originalSizeMB, 2)) MB | New Size: $([math]::Round($compressedSizeMB, 2)) MB | Saved: $([math]::Round($savedPercent, 2))%"
        Write-Host $logMessage
        Add-Content -Path $logPath -Value $logMessage

        Add-Content -Path $deleteListPath -Value $file.FullName

        $totalProcessed++
        $totalOriginalSize += $file.Length
        $totalCompressedSize += $compressedFile.Length
    } else {
        $errorMsg = "Error compressing $($file.Name)"
        Write-Host $errorMsg -ForegroundColor Red
        Add-Content -Path $logPath -Value $errorMsg
    }
}

if ($totalProcessed -gt 0) {
    $totalOrigGB = $totalOriginalSize / 1GB
    $totalCompGB = $totalCompressedSize / 1GB
    $totalSavedPercent = 0
    if ($totalOrigGB -gt 0) {
        $totalSavedPercent = (($totalOrigGB - $totalCompGB) / $totalOrigGB) * 100
    }

    $summaryMsg = "`n--- SUMMARY ---`nTotal Files Processed: $totalProcessed`nTotal Original Size: $([math]::Round($totalOrigGB, 2)) GB`nTotal Compressed Size: $([math]::Round($totalCompGB, 2)) GB`nTotal Space Saved: $([math]::Round($totalSavedPercent, 2))%"

    Write-Host $summaryMsg
    Add-Content -Path $logPath -Value $summaryMsg
} else {
    Write-Host "`n--- SUMMARY ---`nNo files were compressed."
    Add-Content -Path $logPath -Value "`n--- SUMMARY ---`nNo files were compressed."
}

args.CommandLine:
$completed = @(Get-Content "C:\Users\renu5\Downloads\Takeout\delete_list.txt")
$totalOriginal = 0
$totalCompressed = 0

foreach ($f in $completed) {
    if (Test-Path $f) { $totalOriginal += (Get-Item $f).Length }

    $file = Get-Item $f
    $basename = $file.BaseName
    $extension = $file.Extension
    $dir = $file.DirectoryName
    $outputFile = Join-Path $dir "$basename C$extension"
    if (Test-Path $outputFile) { $totalCompressed += (Get-Item $outputFile).Length }
}

Write-Host "`n--- FINAL SUMMARY ---"
Write-Host "Total Files Compressed: $($completed.Count)"
Write-Host "Total Original Size: $([math]::Round($totalOriginal / 1GB, 2)) GB"
Write-Host "Total Compressed Size: $([math]::Round($totalCompressed / 1GB, 2)) GB"
if ($totalOriginal -gt 0) {
    Write-Host "Total Space Saved: $([math]::Round((($totalOriginal - $totalCompressed) / $totalOriginal) * 100, 2))%"
}

$rawList = Get-Content "C:\Users\renu5\Downloads\Takeout\delete_list.txt"
$verifiedList = @()
$missingCompressed = @()

# First check from the script run 
foreach ($f in $rawList) {
    if (-not (Test-Path $f)) {
        continue # Original already deleted or moved
    }

    $file = Get-Item $f
    $basename = $file.BaseName
    $extension = $file.Extension
    $dir = $file.DirectoryName
    $compressedPath = Join-Path $dir "$basename C$extension"

    # Triple check: does the compressed file exist and is it not empty?
    if ((Test-Path $compressedPath) -and ((Get-Item $compressedPath).Length -gt 10KB)) {
        $verifiedList += $f
    } else {
        $missingCompressed += $f
    }
}

$verifiedList | Select-Object -Unique | Out-File "C:\Users\renu5\Downloads\Takeout\verified_delete_list.txt"

Write-Host "Total in raw list: $($rawList.Count)"
Write-Host "Total safely verified: $($verifiedList.Count)"
Write-Host "Missing or empty compressed files: $($missingCompressed.Count)"

$targetPath = "C:\Users\renu5\Downloads\Takeout"
$allOriginals = Get-ChildItem -Path $targetPath -Filter "*.mp4" -Recurse | Where-Object {
    $_.Length -ge 20MB -and $_.Name -notmatch " C\.mp4$"
}

$verified = @()
$missing = @()

foreach ($file in $allOriginals) {
    $basename = $file.BaseName
    $extension = $file.Extension
    $dir = $file.DirectoryName
    $compressedPath = Join-Path $dir "$basename C$extension"

    if ((Test-Path $compressedPath) -and ((Get-Item $compressedPath).Length -gt 10KB)) {
        $verified += [PSCustomObject]@{
            Original = $file.FullName
            Copy = $compressedPath
        }
    } else {
        $missing += $file.FullName
    }
}

Write-Host "`n--- PRECISION CHECK RESULTS ---"
Write-Host "Total original files (>= 20MB) found in Takeout: $($allOriginals.Count)"
Write-Host "Files WITH a confirmed, valid compressed copy: $($verified.Count)"
Write-Host "Files WITHOUT a valid compressed copy: $($missing.Count)"

if ($missing.Count -gt 0) {
    Write-Host "`nThe following files DO NOT have a compressed copy:"
    $missing | ForEach-Object { Write-Host "- $_" }
}

$targetPath = "C:\Users\renu5\Downloads\Takeout"
$allOriginals = Get-ChildItem -Path $targetPath -Filter "*.mp4" -Recurse | Where-Object {
    $_.Length -ge 20MB -and $_.Name -notmatch " C\.mp4$"
}

$deletedCount = 0
$failedToCompress = @()

foreach ($file in $allOriginals) {
    $basename = $file.BaseName
    $extension = $file.Extension
    $dir = $file.DirectoryName
    $compressedPath = Join-Path $dir "$basename C$extension"

    if ((Test-Path $compressedPath) -and ((Get-Item $compressedPath).Length -gt 10KB)) {
        Remove-Item $file.FullName -Force
        $deletedCount++
    } else {
        Write-Host "Attempting to compress left file: $($file.Name)..."
        # Redirect ffmpeg output to log file to avoid clutter
        & ffmpeg -y -i $file.FullName -c:v libx264 -crf 28 -preset fast -c:a aac -b:a 128k $compressedPath 2>&1 | Out-File "C:\Users\renu5\Downloads\Takeout\ffmpeg_retry_log.txt"

        if ($LASTEXITCODE -eq 0 -and (Test-Path $compressedPath) -and ((Get-Item $compressedPath).Length -gt 10KB)) {
            Write-Host "Success! Now deleting original..."
            Remove-Item $file.FullName -Force
            $deletedCount++
        } else {
            Write-Host "Failed to compress again: $($file.Name). Check ffmpeg_retry_log.txt for details."
            $failedToCompress += $file.FullName
        }
    }
}

Write-Host "`n--- FINAL DELETION SUMMARY ---"
Write-Host "Deleted $deletedCount original files safely."
if ($failedToCompress.Count -gt 0) {
    Write-Host "Could not compress (and therefore did not delete) these files:"
    $failedToCompress | ForEach-Object { Write-Host "- $_" }
}

